update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p081","body":"جب کوئی بات کرتے ہو ، کتنے اچھے لگتے ہو\nجب کوئی بات سنتے ہو ، کتنے اچھے لگتے ہو\n\nجھکے آبشار کبھی تو کبھی اَوپری نار نگاہیں\nجس صورت بھی رہتے ہو ، کتنے اچھے لگتے ہو\n\nکسی موڑ پہ اکثر تنہائی کا احساس دلا کر، پھر\nپلٹ کے بھی تکتے ہو ، کتنے اچھے لگتے ہو\n\nرات نبھاتے ہو وعدے تم سبھی لوٹ آنے کے\nچلو خیالوں میں تو ملتے ہو ، کتنے اچھے لگتے ہو\n\nسنا ہے ملاقاتوں کا سلسلہ خوب جاری ہے\nجس لیے بھی سنورتے ہو ، کتنے اچھے لگتے ہو\n\nشام اکثر میری غزلوں کو چائے کے کپ کے ساتھ\nاحمد ؔ  اپنے ہونٹوں پہ دھرتے ہو ، کتنے اچھے لگتے ہو"},{"slug":"tum-p082","body":"بلاوجہ بےقراری کیوں ہوتی ہے؟\nپل پل انتظاری کیوں ہوتی ہے؟\n\nخواب کو خواب ہی سمجھنا ہے\n\nتو یہ نیند طاری کیوں ہوتی ہے؟\nدل کے موسم پہ چھائی رہتی ہے خزاں\n\nفضا بادِ بہاری کیوں ہوتی ہے؟\nگھر گھر ہوتا ہے کسی غم کا سایہ\n\nخوشی بازاری کیوں ہوتی ہے؟\nکسی کے کسی کو مل جانے سے\n\nکسی کی دل آزاری کیوں ہوتی ہے؟\nشہر بدر ہو کے جدھر مسافر رکیں\n\nوہی دہلیز ہماری کیوں ہوتی ہے؟\n\nتم ہی سے جیت کے تم کو  احمد ؔ\nمیں نے بازی ہاری کیوں ہوتی ہے؟"},{"slug":"tum-p083","body":"کیا رکھا ہے آخر اس پریت میں\nبس غم ہی ہیں اس ذیست میں\n\nہم سے محبت کا دعوےدار شخص\nالجھا بیٹھا ہے رسم و ریت میں\n\nمت پوچھ اس کی باتوں کی مٹھاس\nکچھ نہیں رکھا سر سنگیت میں\n\nاحمد وہ دلفریب ہے پھر کیوں ہے شامل\nہر گفتگو، خیالات ، غزل اور گیت میں"},{"slug":"tum-p084","body":"گل تھے کم ، خار بہت تھے\nمیرے سوا بھی اسکے یار بہت تھے\n\nوہ آخری بار بھی اسی تپاک سے ملا تھا\nان آنکھوں میں خوشی کے آثار بہت تھے\n\nتیرے بعد ہنسنے کا مغالطہ ہی رہا\nتیرے بعد ہم خود سے بےزار بہت تھے\n\nخشک پلکوں میں چھپے راز نہیں پڑھ پائے\nیوں کہنے کو میرے غمگسار بہت تھے\n\nکاش سکون کی سانسیں بھی ہوتیں احمد ؔ\nیہ گھر ویسے تو پائیدار بہت تھے"},{"slug":"tum-p085","body":"خواب ہیں اور اشارے ہیں\nاب بھی ہم تمہارے ہیں\n\nملنے ملانے کے چکر میں\nبہت لوگ ہم نے ہارے ہیں\n\nنہ کوئی آس ہے ، نہ پیاس ہے\nدل شکستہ ضبط کنارے ہیں\n\nعمر ہوئی اسے اب دیکھا\nمدت بعد بال سنوارے ہیں\n\nوہ اک شخص جس نے بھلا دیا\nفلک پہ اور بھی کتنے تارے ہیں\n\nاور کیا کہوں کیا ستم ہوا\nوقت مشکل اپنے ساتھ  گزارے ہیں\n\nہم جو یوں خوشحال دکھتے ہیں\nاحمد ؔ بہت رنجشوں کے مارے ہیں"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
